import type { RepoFile, RepoTarget } from "./types";

const CODE_EXT = new Set([
  ".ts", ".tsx", ".js", ".jsx", ".py", ".go", ".rs", ".java", ".rb", ".php",
  ".vue", ".svelte", ".cs", ".kt", ".swift", ".yaml", ".yml", ".json",
  ".tf", ".hcl", ".dockerfile", ".sh", ".bash", ".env.example",
]);

const PRIORITY_NAMES = new Set([
  "package.json", "package-lock.json", "yarn.lock", "pnpm-lock.yaml",
  "requirements.txt", "Pipfile", "go.mod", "Cargo.toml", "composer.json",
  "Dockerfile", "docker-compose.yml", "docker-compose.yaml",
  ".github/workflows", "terraform", "main.tf", "variables.tf",
]);

const MAX_FILES = 60;
const MAX_FILE_BYTES = 80_000;
const MAX_TOTAL_BYTES = 400_000;

export function parseRepoUrl(input: string): { owner: string; repo: string } | null {
  const trimmed = input.trim();
  const patterns = [
    /github\.com\/([^/\s]+)\/([^/\s#?]+)/i,
    /^([^/\s]+)\/([^/\s]+)$/,
  ];
  for (const re of patterns) {
    const m = trimmed.match(re);
    if (m) {
      const owner = m[1].replace(/\.git$/, "");
      const repo = m[2].replace(/\.git$/, "").replace(/\/$/, "");
      if (owner && repo) return { owner, repo };
    }
  }
  return null;
}

function ghHeaders(token?: string): HeadersInit {
  const h: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "ThreatLens-Security-Agent/1.0",
  };
  if (token) h.Authorization = `Bearer ${token}`;
  return h;
}

export async function fetchRepoMeta(
  owner: string,
  repo: string,
  token?: string,
): Promise<RepoTarget | null> {
  const res = await fetch(`https://api.github.com/repos/${owner}/${repo}`, {
    headers: ghHeaders(token),
  });
  if (!res.ok) return null;
  const data = await res.json();
  const languagesRes = await fetch(`https://api.github.com/repos/${owner}/${repo}/languages`, {
    headers: ghHeaders(token),
  });
  const langs = languagesRes.ok ? Object.keys(await languagesRes.json()) : [];
  const stack = detectStackFromMeta(data, langs);
  return {
    url: data.html_url,
    owner,
    repo,
    defaultBranch: data.default_branch ?? "main",
    languages: langs,
    stack,
  };
}

function detectStackFromMeta(data: { topics?: string[] }, langs: string[]): string[] {
  const stack = new Set<string>(langs.slice(0, 5));
  for (const t of data.topics ?? []) {
    if (/react|next|vue|angular|django|flask|fastapi|express|nestjs|terraform|kubernetes|docker/i.test(t)) {
      stack.add(t);
    }
  }
  if (langs.includes("TypeScript") || langs.includes("JavaScript")) stack.add("Node.js");
  if (langs.includes("Python")) stack.add("Python");
  if (langs.includes("Go")) stack.add("Go");
  return [...stack];
}

type TreeItem = { path: string; type: string; size?: number };

function scorePath(path: string): number {
  const lower = path.toLowerCase();
  let score = 0;
  if (PRIORITY_NAMES.has(path.split("/").pop() ?? "")) score += 100;
  if (lower.includes(".github/workflows")) score += 90;
  if (lower.includes("auth") || lower.includes("security") || lower.includes("api")) score += 40;
  if (lower.includes("middleware") || lower.includes("controller") || lower.includes("route")) score += 30;
  if (lower.endsWith(".env") || lower.includes("secret")) score += 50;
  if (lower.includes("node_modules") || lower.includes("dist/") || lower.includes("build/")) score -= 200;
  if (lower.includes(".min.") || lower.endsWith(".lock")) score -= 20;
  const ext = lower.slice(lower.lastIndexOf("."));
  if (CODE_EXT.has(ext)) score += 20;
  return score;
}

export async function fetchRepoFiles(
  owner: string,
  repo: string,
  branch: string,
  token?: string,
): Promise<RepoFile[]> {
  const treeRes = await fetch(
    `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    { headers: ghHeaders(token) },
  );
  if (!treeRes.ok) throw new Error(`Cannot read repository tree (${treeRes.status})`);

  const tree = await treeRes.json();
  const blobs: TreeItem[] = (tree.tree ?? [])
    .filter((t: TreeItem) => t.type === "blob")
    .filter((t: TreeItem) => {
      const ext = t.path.slice(t.path.lastIndexOf(".")).toLowerCase();
      const name = t.path.split("/").pop() ?? "";
      return CODE_EXT.has(ext) || PRIORITY_NAMES.has(name) || name === "Dockerfile";
    })
    .filter((t: TreeItem) => (t.size ?? 0) < MAX_FILE_BYTES)
    .sort((a: TreeItem, b: TreeItem) => scorePath(b.path) - scorePath(a.path))
    .slice(0, MAX_FILES);

  const files: RepoFile[] = [];
  let totalBytes = 0;

  for (const item of blobs) {
    if (totalBytes >= MAX_TOTAL_BYTES) break;
    const content = await fetchFileContent(owner, repo, item.path, branch, token);
    if (!content) continue;
    totalBytes += content.length;
    files.push({
      path: item.path,
      content,
      language: inferLanguage(item.path),
      size: content.length,
    });
  }

  return files;
}

export async function fetchFileContent(
  owner: string,
  repo: string,
  path: string,
  ref: string,
  token?: string,
): Promise<string | null> {
  const res = await fetch(
    `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(path)}?ref=${ref}`,
    { headers: ghHeaders(token) },
  );
  if (!res.ok) return null;
  const data = await res.json();
  if (data.encoding === "base64" && data.content) {
    try {
      return atob(data.content.replace(/\n/g, ""));
    } catch {
      return null;
    }
  }
  return null;
}

function inferLanguage(path: string): string {
  const ext = path.slice(path.lastIndexOf(".")).toLowerCase();
  const map: Record<string, string> = {
    ".ts": "typescript", ".tsx": "typescript", ".js": "javascript", ".jsx": "javascript",
    ".py": "python", ".go": "go", ".rs": "rust", ".java": "java", ".rb": "ruby",
    ".php": "php", ".yaml": "yaml", ".yml": "yaml", ".json": "json", ".tf": "hcl",
    ".sh": "shell", ".vue": "vue", ".cs": "csharp",
  };
  if (path.endsWith("Dockerfile")) return "dockerfile";
  return map[ext] ?? "text";
}

export function buildPrUrl(owner: string, repo: string, title: string, body: string): string {
  const params = new URLSearchParams({
    expand: "1",
    title,
    body,
  });
  return `https://github.com/${owner}/${repo}/compare?${params.toString()}`;
}
